def fill_order_copy(apps, schema_editor):
    """Copy the shop and buyer of the existing orders into the orders."""
    Order = apps.get_model("bpforge", "Order")
    orders = Order.objects.select_related(
        "owner__user",
        "owner__corporation",
        "owner__character__character",
        "requesting_user__profile__main_character",
    )
    for order in orders.iterator():
        owner = order.owner
        if owner.corporation:
            order.owner_name = owner.corporation.corporation_name
            order.owner_corporation_id = owner.corporation.corporation_id
        elif owner.character:
            order.owner_name = owner.character.character.character_name
            order.owner_corporation_id = owner.character.character.corporation_id
        else:
            order.owner_name = owner.user.username
        order.seller_user = owner.user

        buyer = order.requesting_user
        try:
            order.requesting_user_name = buyer.profile.main_character.character_name
        except AttributeError:
            order.requesting_user_name = buyer.username

        order.save(
            update_fields=[
                "owner_name",
                "owner_corporation_id",
                "seller_user",
                "requesting_user_name",
            ]
        )


